'use strict';
const el=id=>document.getElementById(id), escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const records=CATALOG.records, byId=new Map(records.map(r=>[r.id,r])), key='gd-concept-pilot-v1';
const outcomeNames={assisted:'Performance with AI',unaided:'Immediate unaided performance',retention:'Later unaided retention',agency:'Agency / control',other:'Other outcome',unknown:'Unknown'};
const durationNames={immediate:'Immediate / same session',days:'Days',weeks:'Weeks',months:'Months or longer',unknown:'Unknown'};
const initialQueue=records.filter(r=>r.kind==='study'&&r.landscape.some(c=>['human','both'].includes(c.side))&&GDConcepts.match(r,GDConcepts.defaults).length).sort((a,b)=>GDConcepts.match(b,GDConcepts.defaults).length-GDConcepts.match(a,GDConcepts.defaults).length||a.id.localeCompare(b.id)).slice(0,40).map(r=>r.id);
let rules=GDConcepts.validateRules(GDConcepts.defaults),reviews={},queue=[...initialQueue],gapNote='',selected=null,cache=new Map(),matrixRows=[],drafts={};
function validateWorkspace(input){
 if(!input||input.schemaVersion!==1)throw Error('Unsupported workspace version.');
 const nextRules=GDConcepts.validateRules(input.rules);if(!Array.isArray(input.queue)||input.queue.length>700||new Set(input.queue).size!==input.queue.length||input.queue.some(id=>!byId.has(id)))throw Error('Invalid review queue.');
 if(!input.reviews||typeof input.reviews!=='object'||Array.isArray(input.reviews))throw Error('Invalid reviews.');
 const nextReviews={};for(const [id,r]of Object.entries(input.reviews)){if(!byId.has(id))throw Error('Unknown reference.');nextReviews[id]=GDConcepts.validateReview(r);}
 if(typeof input.gapNote!=='string'||input.gapNote.length>20000)throw Error('Invalid research note.');
 return {rules:nextRules,reviews:nextReviews,queue:[...input.queue],gapNote:input.gapNote};
}
function payload(){return {schemaVersion:1,rules,reviews,queue,gapNote};}
function applyWorkspace(w){rules=w.rules;reviews=w.reviews;queue=w.queue;gapNote=w.gapNote;cache.clear();}
try{const saved=localStorage.getItem(key);if(saved)applyWorkspace(validateWorkspace(JSON.parse(saved)));}catch(e){el('pilot-message').textContent='Saved workspace could not be loaded: '+e.message;}
function persist(){try{localStorage.setItem(key,JSON.stringify(payload()));el('storage-note').textContent='Workspace saved in this browser. Export to preserve or share it.';}catch(e){el('storage-note').textContent='Storage unavailable. Export before leaving to preserve your work.';}}
function matches(r){if(!cache.has(r.id))cache.set(r.id,GDConcepts.match(r,rules));return cache.get(r.id);}
const options=(map,value)=>Object.entries(map).map(([id,label])=>`<option value="${id}"${id===value?' selected':''}>${escapeHTML(label)}</option>`).join('');
function collectionRows(){const ids=new Set(queue),query=GDConcepts.norm(el('pilot-search').value).split(' ').filter(Boolean);return records.filter(r=>(el('collection').value==='all'||ids.has(r.id))&&query.every(t=>GDConcepts.norm(r.title+' '+r.citation).includes(t)));}
function filtered(){return collectionRows().filter(r=>(!el('concept-filter').value||matches(r).some(m=>m.id===el('concept-filter').value))&&(el('review-filter').value==='all'||(reviews[r.id]?.status||'unreviewed')===el('review-filter').value));}
function tags(r){return matches(r).map(m=>`<span class="tag suggested">${escapeHTML(rules.find(c=>c.id===m.id).label)}</span>`).join('');}
function renderConcepts(){
 el('concepts').innerHTML=rules.map(c=>`<div class="concept-card"><h3>${escapeHTML(c.label)}</h3><p>${escapeHTML(c.definition)}</p><p>Pathway nodes: ${escapeHTML(c.nodes.join(' · '))}</p><label>Matching phrases<textarea data-rules="${c.id}">${escapeHTML(c.terms.join('\n'))}</textarea></label><p id="rule-count-${c.id}"></p><button data-filter="${c.id}">Explore concept →</button></div>`).join('');
 el('concept-filter').innerHTML='<option value="">All concepts</option>'+rules.map(c=>`<option value="${c.id}">${escapeHTML(c.label)}</option>`).join('');
}
function drawGraph(rows){
 const visible=[...rows].filter(r=>matches(r).length).sort((a,b)=>matches(b).length-matches(a).length||a.id.localeCompare(b.id)).slice(0,30),points={};
 rules.forEach((c,i)=>{const a=-Math.PI/2+i*2*Math.PI/rules.length;points[c.id]=[470+310*Math.cos(a),320+235*Math.sin(a)];});
 let lines='',dots='';visible.forEach((r,i)=>{const a=i*2.399963,x=470+Math.cos(a)*(45+Math.sqrt(i)*22),y=320+Math.sin(a)*(40+Math.sqrt(i)*19);matches(r).forEach(m=>{const p=points[m.id];lines+=`<line x1="${x}" y1="${y}" x2="${p[0]}" y2="${p[1]}" stroke="#9cb7a6" stroke-dasharray="4 4" opacity=".65"/>`;});dots+=`<g data-paper="${r.id}" class="paper-dot"><title>${escapeHTML(r.title)}</title><circle cx="${x}" cy="${y}" r="13" fill="transparent"/><circle cx="${x}" cy="${y}" r="${selected===r.id?8:5}" fill="${selected===r.id?'#a95b27':'#315e49'}"/></g>`;});
 el('pilot-graph').innerHTML=lines+rules.map(c=>{const[x,y]=points[c.id],n=rows.filter(r=>matches(r).some(m=>m.id===c.id)).length;return `<g data-filter="${c.id}" class="topic"><title>${escapeHTML(c.definition)}</title><circle cx="${x}" cy="${y}" r="13" fill="${el('concept-filter').value===c.id?'#a95b27':'#2b6a4d'}"/><text x="${x}" y="${y-24}" text-anchor="middle">${escapeHTML(c.label)}</text><text x="${x}" y="${y+34}" text-anchor="middle">${n}</text></g>`;}).join('')+dots;
 el('pilot-count').textContent=`${visible.length} shown · ${rows.length} filtered references`;
}
function renderTable(rows){el('comparison').innerHTML=rows.map(r=>{const v=reviews[r.id],metadata=r.landscape||[],hint=k=>[...new Set(metadata.map(c=>c[k]).filter(Boolean))].join(' / ');return `<tr><td><strong>${escapeHTML(r.title)}</strong><p>${escapeHTML(r.citation)} · ${r.year}</p>${tags(r)}</td><td>${escapeHTML(v?.population||'Unknown')}<p class="note">Catalog setting: ${escapeHTML(hint('domain')||'unknown')}</p></td><td>${escapeHTML(v?.design||'Unknown')}<p class="note">Catalog hint: ${escapeHTML(hint('design')||'unknown')}</p></td><td>${escapeHTML(outcomeNames[v?.outcome||'unknown'])}</td><td>${escapeHTML(durationNames[v?.duration||'unknown'])}<p class="note">Catalog duration: ${escapeHTML(hint('timespan')||'unknown')}</p></td><td>${escapeHTML(v?.status==='checked'?'Source checked by you':v?.status==='excluded'?'Excluded by you':'Unreviewed')}<p><button data-paper="${r.id}">Inspect / review</button></p></td></tr>`;}).join('')||'<tr><td colspan="6">No references match.</td></tr>';}
function renderMatrix(){
 matrixRows=collectionRows().filter(r=>reviews[r.id]?.status==='checked');
 el('matrix').innerHTML=`<table class="matrix"><thead><tr><th>Primary measured outcome</th>${GDConcepts.durations.map(d=>`<th>${durationNames[d]}</th>`).join('')}</tr></thead><tbody>${GDConcepts.outcomes.map(o=>`<tr><th>${outcomeNames[o]}</th>${GDConcepts.durations.map(d=>{const n=matrixRows.filter(r=>reviews[r.id].outcome===o&&reviews[r.id].duration===d).length;return `<td><button data-outcome="${o}" data-duration="${d}" aria-label="${n} checked references: ${escapeHTML(outcomeNames[o])}, ${escapeHTML(durationNames[d])}">${n}</button></td>`;}).join('')}</tr>`).join('')}</tbody></table><p class="note">${matrixRows.length} source-checked references in this collection/search. Initial queue favors papers with multiple concept matches; it is not a systematic or representative sample. Follow-up refers to the classified outcome, not total study duration.</p>`;
 el('cell-records').innerHTML='';
}
function render(){const rows=filtered();rules.forEach(c=>{const count=el('rule-count-'+c.id);if(count)count.textContent=`${records.filter(r=>matches(r).some(m=>m.id===c.id)).length} matching catalog references`;});drawGraph(rows);renderTable(rows);renderMatrix();el('review-count').textContent=`${rows.length} references · ${rows.filter(r=>reviews[r.id]?.status==='checked').length} checked`;}
function stashDraft(){const form=el('review-form');if(form&&selected)drafts[selected]=Object.fromEntries(new FormData(form));}
function reviewPanel(){
 const r=byId.get(selected);if(!r)return;const v=drafts[r.id]||reviews[r.id]||{population:'',design:'',outcome:'unknown',duration:'unknown',note:'',quote:'',locator:'',status:'unreviewed'},ms=matches(r),ids=new Set(ms.map(m=>m.id));
 const related=records.filter(p=>p.id!==r.id).map(p=>({paper:p,shared:matches(p).filter(m=>ids.has(m.id))})).filter(p=>p.shared.length).sort((a,b)=>b.shared.length-a.shared.length||a.paper.id.localeCompare(b.paper.id)).slice(0,5);
 el('review-panel').innerHTML=`<p class="eyebrow">PAPER → CONCEPT → PAPER</p><h2>${escapeHTML(r.title)}</h2><p>${escapeHTML(r.citation)}</p><a href="${escapeHTML(r.url)}" target="_blank" rel="noopener noreferrer">Read original source ↗</a><h3>Why it connects</h3>${ms.map(m=>`<p class="quote"><b>${escapeHTML(rules.find(c=>c.id===m.id).label)}</b><br>${m.hits.map(h=>`“${escapeHTML(h.term)}” · ${h.field}`).join('<br>')}</p>`).join('')||'<p>No matches under current rules.</p>'}<details><summary>Related papers · shared concepts only</summary>${related.map(({paper,shared})=>`<div class="related"><button data-paper="${paper.id}">${escapeHTML(paper.title)}</button><p class="note">Shared: ${shared.map(m=>escapeHTML(rules.find(c=>c.id===m.id).label)).join(', ')}</p></div>`).join('')||'<p>No related papers under these rules.</p>'}</details><h3>Source-review record</h3><p class="note">Check the original source. Use the population and follow-up for this outcome. Saving your assessment does not establish causation or independent verification.</p><form id="review-form" class="review-form"><label>Population / sample<input name="population" maxlength="5000" value="${escapeHTML(v.population)}"></label><label>Study design<input name="design" maxlength="5000" value="${escapeHTML(v.design)}"></label><label>Primary outcome<select name="outcome">${options(outcomeNames,v.outcome)}</select></label><label>Outcome follow-up<select name="duration">${options(durationNames,v.duration)}</select></label><label>Source excerpt<textarea name="quote" maxlength="5000">${escapeHTML(v.quote)}</textarea></label><label>Source page / section<input name="locator" maxlength="5000" value="${escapeHTML(v.locator)}"></label><label>Interpretation / limits<textarea name="note" maxlength="5000">${escapeHTML(v.note)}</textarea></label><label>Review status<select name="status">${options({unreviewed:'Draft / unreviewed',checked:'Source checked by me',excluded:'Exclude from this pilot'},v.status)}</select></label><button type="submit">Save review</button><p id="review-message" role="status"></p></form>`;
 el('review-form').onsubmit=e=>{e.preventDefault();try{const input=Object.fromEntries(new FormData(e.target));reviews[r.id]=GDConcepts.validateReview(input);delete drafts[r.id];persist();render();el('review-message').textContent='Review saved.';}catch(err){el('review-message').textContent=err.message;}};
}
document.addEventListener('click',e=>{const p=e.target.closest('[data-paper]');if(p){stashDraft();selected=p.dataset.paper;reviewPanel();drawGraph(filtered());return;}const c=e.target.closest('[data-filter]');if(c){el('concept-filter').value=c.dataset.filter;render();return;}const cell=e.target.closest('[data-outcome]');if(cell){const rows=matrixRows.filter(r=>reviews[r.id].outcome===cell.dataset.outcome&&reviews[r.id].duration===cell.dataset.duration);el('cell-records').innerHTML=`<h3>${escapeHTML(outcomeNames[cell.dataset.outcome])} · ${escapeHTML(durationNames[cell.dataset.duration])}</h3>`+(rows.map(r=>`<p><button data-paper="${r.id}">${escapeHTML(r.title)}</button></p>`).join('')||'<p>No source-checked references in this cell of this collection. Further searching is needed.</p>');}});
el('concepts').addEventListener('input',e=>{if(!e.target.dataset.rules)return;try{const next=rules.map(c=>({...c,terms:c.id===e.target.dataset.rules?e.target.value.split('\n').map(s=>s.trim()).filter(Boolean):c.terms}));rules=GDConcepts.validateRules(next);cache.clear();persist();render();stashDraft();reviewPanel();el('pilot-message').textContent='Keyword rules applied. Saved evidence reviews are unchanged.';}catch(err){el('pilot-message').textContent=err.message;}});
['pilot-search','collection','concept-filter','review-filter'].forEach(id=>el(id).addEventListener(id==='pilot-search'?'input':'change',render));
el('reset-rules').onclick=()=>{rules=GDConcepts.validateRules(GDConcepts.defaults);cache.clear();renderConcepts();persist();render();stashDraft();reviewPanel();el('pilot-message').textContent='Default rules restored. Reviews preserved.';};
el('gap-note').value=gapNote;el('gap-note').maxLength=20000;el('gap-note').oninput=e=>{gapNote=e.target.value;persist();};
el('export-pilot').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(payload(),null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='gd-concept-workspace.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
el('import-pilot').onclick=()=>el('import-file').click();
el('import-file').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>3000000)throw Error('Workspace file too large.');const incoming=validateWorkspace(JSON.parse(await f.text()));const backup=JSON.stringify(payload());try{localStorage.setItem(key+'-before-import',backup);}catch(_){throw Error('Could not save a backup; export your current workspace first.');}applyWorkspace(incoming);drafts={};selected=null;el('review-panel').innerHTML='<h2>Workspace imported</h2><p>Select a paper to review.</p>';renderConcepts();el('gap-note').value=gapNote;persist();render();el('pilot-message').innerHTML='Workspace replaced. <button id="undo-import">Undo import</button>';el('undo-import').onclick=()=>{applyWorkspace(validateWorkspace(JSON.parse(backup)));drafts={};selected=null;el('review-panel').innerHTML='<h2>Import undone</h2><p>Select a paper to review.</p>';renderConcepts();el('gap-note').value=gapNote;persist();render();el('pilot-message').textContent='Previous workspace restored.';};}catch(err){el('pilot-message').textContent='Import failed: '+err.message;}e.target.value='';};
renderConcepts();persist();render();
